process.inputbuf:
SET NOCOUNT ON;
SET XACT_ABORT OFF;
DECLARE @a int,@s binary(8);SELECT @a=MaTK,@s=SecurityStamp FROM dbo.TAIKHOAN WHERE MaTK=1;
DECLARE @from datetime2(7)=CONVERT(datetime2(7),CONVERT(date,SYSDATETIME())),@start datetime2(7)=SYSDATETIME(),@i int=0;
WHILE (SELECT StartedAt FROM dbo.G07RaceGate WHERE Id=1) IS NULL
BEGIN
 IF DATEDIFF(second,@start,SYSDATETIME())>120 RETURN;
 WAITFOR DELAY '00:00:00.050';
END
WHILE (SELECT StopAt FROM dbo.G07RaceGate WHERE Id=1) IS NULL AND @i<200000
BEGIN
 BEGIN TRY
  DECLARE @until datetime2(7)=DATEADD(second,-1,SYSDATETIME());
  -- INSERT EXEC mo transaction an => procedure chan @@TRANCOUNT<>0, phai goi truc tiep.
  EXEC dbo.sp_DashboardAnalyticsSources @Actor=@a,@Stamp=@s,@Kind='product',@From=@from,@Until=@until,@Product='SP999';
  SET @i+=1;
 END TRY BEGIN CATCH
  DECLARE @err int=ERROR_NUMBER(),@msg nvarchar(400)=ERROR_MESSAGE();
  INSERT dbo.G07RaceLog(Session,Iteration,ErrorNumber,Message) VALUES('reader',@i,@err,@msg);
  SET @i+=1;
 END CATCH;
END
INSERT dbo.G07RaceLog

SET NOCOUNT ON;
SET XACT_ABORT OFF;
DECLARE @a int,@s binary(8);SELECT @a=MaTK,@s=SecurityStamp FROM dbo.TAIKHOAN WHERE MaTK=1;
DECLARE @start datetime2(7)=SYSDATETIME();
WHILE (SELECT StartedAt FROM dbo.G07RaceGate WHERE Id=1) IS NULL
BEGIN
 IF DATEDIFF(second,@start,SYSDATETIME())>120
 BEGIN INSERT dbo.G07RaceLog(Session,Iteration,ErrorNumber,Message) VALUES('writer',0,0,N'gate timeout');RETURN;END
 WAITFOR DELAY '00:00:00.050';
END
DECLARE @i int=1,@total int=200000,@code char(10),@req uniqueidentifier,@rev binary(8),
 @err int,@msg nvarchar(400),@token binary(32),@payable decimal(38,0);
DECLARE @c TABLE(Kind varchar(20),Code char(10));
DECLARE @pay dbo.DanhSachThanhToan;
WHILE @i<=@total AND (SELECT StopAt FROM dbo.G07RaceGate WHERE Id=1) IS NULL
BEGIN
 BEGIN TRY
  DELETE @c;INSERT @c EXEC dbo.sp_CapMa 'HOADON';SELECT @code=Code FROM @c;
  SET @req=NEWID();
  EXEC dbo.sp_TaoHoaDon @Actor=@a,@Stamp=@s,@Code=@code,@RequestId=@req,@Channel=N'Mang di',@Product='SP999',@Quantity=1,@Note=N'Race';
  SELECT @rev

