SET XACT_ABORT OFF;
DECLARE @a int,@s binary(8);SELECT @a=MaTK,@s=SecurityStamp FROM dbo.TAIKHOAN WHERE MaTK=1;
DECLARE @start datetime2(7)=SYSDATETIME();
